<template><div><div class="evidence-images"><a v-for="row in images" :key="row.id" :href="row.url" target="_blank" rel="noopener noreferrer"><img :src="row.url" alt="业务凭证图片"/><span>查看原图</span></a></div><p v-if="loading" class="meta">正在核对附件权限…</p><p v-if="error" class="error">{{error}} <Button type="text" @click="load">重试</Button></p><p v-if="!loading&&!error&&!images.length" class="meta">未提交图片凭证。</p></div></template>
<script>
import {s45Asset} from '@/api/stage45';import {managerSession} from '@/libs/manager-session';
export default{props:{ids:{type:Array,default:()=>[]}},data(){return{images:[],loading:false,error:'',ticket:0}},watch:{ids:{handler(){this.load()},immediate:true}},beforeDestroy(){this.ticket++;this.clear()},methods:{clear(){this.images.forEach(r=>URL.revokeObjectURL(r.url));this.images=[]},async load(){const run=++this.ticket,owner=managerSession.snapshot();this.clear();this.error='';this.loading=true;try{const settled=await Promise.all(this.ids.map(async id=>{try{return{id,url:await s45Asset(id)}}catch(error){return{error}}}));const rows=settled.filter(r=>r.url),failure=settled.find(r=>r.error);if(failure){rows.forEach(r=>URL.revokeObjectURL(r.url));throw failure.error}if(run===this.ticket&&managerSession.sameSession(owner))this.images=rows;else rows.forEach(r=>URL.revokeObjectURL(r.url))}catch(e){if(run===this.ticket)this.error=e.message}finally{if(run===this.ticket)this.loading=false}}}};
</script>
